def transform(grid):
    """
    Task-607a9d08:
    For single-cell connected components, check all 8 neighbors.
    - If all 8 neighbors are the same non-background color N, change to N
    - Otherwise, change to background (2)
    """
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])
    bg = 2

    # Find all single-cell components (cells not connected to same-colored neighbors)
    visited = [[False] * cols for _ in range(rows)]
    single_cells = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and not visited[r][c]:
                color = grid[r][c]
                # Do BFS to find connected component
                comp = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == color:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                if len(comp) == 1:
                    single_cells.append((r, c))

    # Apply transformation
    result = [row[:] for row in grid]  # Copy

    for r, c in single_cells:
        # Get all 8 neighbors
        neighbors = {}
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    n = grid[nr][nc]
                    neighbors[n] = neighbors.get(n, 0) + 1

        # Check if all 8 neighbors are the same non-bg color
        non_bg = {k: v for k, v in neighbors.items() if k != bg}

        if len(non_bg) == 1 and non_bg[0] == 8:  # All 8 neighbors are the same
            # Find which color
            target_color = [k for k, v in non_bg.items() if v == 8][0]
            result[r][c] = target_color
        else:
            result[r][c] = bg

    return result

