def get_orthogonal_neighbors(r, c, rows, cols):
    """Get all orthogonal (up, down, left, right) neighbors."""
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
