    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 2 and (r, c) not in visited:
                color = grid[r][c]
                comp_positions = []
                queue = deque([(r, c)])
                visited.add((r, c))

                while queue:
                    curr_r, curr_c = queue.popleft()
                    comp_positions.append((curr_r, curr_c))

                    for nr, nc in get_orthogonal_neighbors(curr_r, curr_c, rows, cols):
                        if grid[nr][nc] == color and (nr, nc) not in visited:
